import{_ as t,o as a,c as o,a0 as n}from"./chunks/framework.DQOulFGV.js";const u=JSON.parse('{"title":"Back up a Mac to Backblaze B2","description":"Encrypted, scheduled Mac backups to your own Backblaze B2 bucket with Keelhaven — the bucket, the application key, the five fields to fill in, and the one lifecycle rule B2 needs.","frontmatter":{"title":"Back up a Mac to Backblaze B2","description":"Encrypted, scheduled Mac backups to your own Backblaze B2 bucket with Keelhaven — the bucket, the application key, the five fields to fill in, and the one lifecycle rule B2 needs."},"headers":[],"relativePath":"guides/backblaze-b2.md","filePath":"guides/backblaze-b2.md"}'),s={name:"guides/backblaze-b2.md"};function r(i,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="back-up-a-mac-to-backblaze-b2" tabindex="-1">Back up a Mac to Backblaze B2 <a class="header-anchor" href="#back-up-a-mac-to-backblaze-b2" aria-label="Permalink to &quot;Back up a Mac to Backblaze B2&quot;">​</a></h1><p>Keelhaven encrypts the folders you pick on your Mac and sends them to a B2 bucket that belongs to you. Backblaze stores data it cannot read, and there is no Keelhaven server in between.</p><p>It takes about ten minutes, most of them on Backblaze&#39;s side.</p><h2 id="_1-create-a-bucket" tabindex="-1">1. Create a bucket <a class="header-anchor" href="#_1-create-a-bucket" aria-label="Permalink to &quot;1. Create a bucket&quot;">​</a></h2><p>In the Backblaze web console, open <strong>Buckets</strong> and click <strong>Create a Bucket</strong>.</p><ul><li><strong>Files in Bucket are:</strong> Private.</li><li><strong>Object Lock:</strong> leave it disabled. It would stop old backups from ever being removed.</li><li><strong>Default Encryption:</strong> either setting works. The backup is already encrypted before it leaves your Mac.</li></ul><p>The bucket now shows an <strong>Endpoint</strong>, something like <code>s3.us-west-004.backblazeb2.com</code>. Step 4 needs it.</p><h2 id="_2-set-the-lifecycle-rule" tabindex="-1">2. Set the lifecycle rule <a class="header-anchor" href="#_2-set-the-lifecycle-rule" aria-label="Permalink to &quot;2. Set the lifecycle rule&quot;">​</a></h2><p>On the bucket, open <strong>Lifecycle Settings</strong> and choose <strong>Keep only the last version of the file</strong>.</p><p>B2 does not delete what a backup tool deletes. It hides it, and keeps billing for it. This one setting is what lets old backups leave your bill — the <a href="/#faq">FAQ</a> has the long version.</p><h2 id="_3-create-an-application-key" tabindex="-1">3. Create an application key <a class="header-anchor" href="#_3-create-an-application-key" aria-label="Permalink to &quot;3. Create an application key&quot;">​</a></h2><p>Open <strong>Application Keys</strong> and click <strong>Add a New Application Key</strong>.</p><ul><li><strong>Allow access to Bucket(s):</strong> the bucket you just made.</li><li><strong>Type of Access:</strong> Read and Write.</li><li><strong>Allow List All Bucket Names:</strong> on. Backblaze asks for it when a single-bucket key is used through the S3 API.</li></ul><p>Backblaze shows a <strong>keyID</strong> and an <strong>applicationKey</strong>. The applicationKey is shown once, so copy both now.</p><p>The master application key at the top of that page will not work: B2&#39;s S3 API only accepts keys made this way.</p><h2 id="_4-connect-keelhaven" tabindex="-1">4. Connect Keelhaven <a class="header-anchor" href="#_4-connect-keelhaven" aria-label="Permalink to &quot;4. Connect Keelhaven&quot;">​</a></h2><p>Click the lighthouse in the menu bar, then <strong>Add Backup Plan…</strong>. Pick your folders. On the next step open <strong>Advanced options</strong> and choose <strong>S3-Compatible</strong>.</p><table tabindex="0"><thead><tr><th>Field</th><th>What goes in</th></tr></thead><tbody><tr><td>Endpoint</td><td>the endpoint from step 1</td></tr><tr><td>Bucket</td><td>the bucket&#39;s name</td></tr><tr><td>Path prefix</td><td>optional — a folder inside the bucket, such as <code>macbook</code></td></tr><tr><td>Access key ID</td><td>the keyID</td></tr><tr><td>Secret access key</td><td>the applicationKey</td></tr></tbody></table><p>Then choose an encryption password, or let Keelhaven generate one. It is kept in your Keychain; put it in your password manager too. Without it nobody can read the backup, you included.</p><h2 id="_5-pick-a-schedule" tabindex="-1">5. Pick a schedule <a class="header-anchor" href="#_5-pick-a-schedule" aria-label="Permalink to &quot;5. Pick a schedule&quot;">​</a></h2><p>Hourly, daily or weekly. The first backup uploads everything. Every one after it sends only what changed.</p><h2 id="worth-knowing" tabindex="-1">Worth knowing <a class="header-anchor" href="#worth-knowing" aria-label="Permalink to &quot;Worth knowing&quot;">​</a></h2><p><strong>The first upload can be slowed down.</strong> <em>Customize this plan</em> on the last step — or <strong>Edit Plan → Advanced</strong> later — has an upload limit, so a large first backup does not take over your connection.</p><p><strong>Backups grow until you say otherwise.</strong> Deleting your data is never Keelhaven&#39;s decision, so retention is off by default. <strong>Edit Plan → Retention</strong> turns it on.</p><p><strong>You can restore without Keelhaven.</strong> The bucket holds a standard <a href="https://restic.net" target="_blank" rel="noreferrer">restic</a> repository:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">restic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3:https://s3.us-west-004.backblazeb2.com/your-bucket</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshots</span></span></code></pre></div><h2 id="another-s3-provider" tabindex="-1">Another S3 provider <a class="header-anchor" href="#another-s3-provider" aria-label="Permalink to &quot;Another S3 provider&quot;">​</a></h2><p>The five fields are the same everywhere. Only the endpoint changes, and the lifecycle rule in step 2 is a B2 matter alone.</p><table tabindex="0"><thead><tr><th>Provider</th><th>Endpoint</th></tr></thead><tbody><tr><td>Amazon S3</td><td><code>s3.amazonaws.com</code></td></tr><tr><td>Cloudflare R2</td><td><code>&lt;account-id&gt;.r2.cloudflarestorage.com</code></td></tr><tr><td>Wasabi</td><td><code>s3.&lt;region&gt;.wasabisys.com</code></td></tr><tr><td>MinIO or another self-hosted server</td><td><code>https://your-host:9000</code></td></tr></tbody></table>',29)])])}const k=t(s,[["render",r]]);export{u as __pageData,k as default};
